mapper.select:
WITH event_pairs AS (SELECT p.device_code,
                            p.device_name,
                            p.occurred_at AS start_time,
                            COALESCE(
                                    MIN(c.occurred_at),
                                    CURRENT_TIMESTAMP
                            )             AS end_time
                     FROM tpm_event_record p
                              LEFT JOIN tpm_event_record c
                                        ON p.device_code = c.device_code
                                            AND c.event_source = #{close}
                                            AND c.occurred_at > p.occurred_at
                                            AND c.occurred_at >= #{startTime}
                                            AND c.occurred_at  <=  #{endTime}
                     WHERE p.event_source = #{power_on}
                       AND p.occurred_at >= #{startTime}
                       AND p.occurred_at  <=   #{endTime}
                     GROUP BY p.id, p.device_code, p.occurred_at)
SELECT device_code,
       device_name,
       FLOOR(SUM(EXTRACT(EPOCH FROM (end_time - start_time)) / 60)) AS run_time
FROM event_pairs
GROUP BY device_code, device_name;
